guidance.correct_example:
import os

def get_db_password() -> Result[str]:
    password = os.environ.get('DB_PASSWORD')
    if password is None:
        return Result.failure('DB_PASSWORD environment variable not set')
    return Result.success(password)

guidance.incorrect_example:
DB_PASSWORD = 'super_secret_123'

def get_db_password() -> Result[str]:
    return Result.success(DB_PASSWORD)
